message.content:
{
  "lines": [
    {
      "text": "Brief aus Stettin, den 21. August 1786"
    },
    {
      "text": "Verehrtester Herr Rath!"
    },
    {
      "text": "Ew. Wohlgeborne Schreiben vom 2ten dieses habe ich in Danzig richtig erhalten. Die Krüge aus"
    },
    {
      "text": "Bunzlau sind wohl verpackt und gehen mit dem Schiffer Hinrichs nach Berlin ab, wo sie Ende des"
    },
    {
      "text": "Monats eintreffen sollen."
    },
    {
      "text": "Was die Karte von Schlesien betrifft, so hat der Buchhändler Korn in Breßlau keine mehr"
    },
    {
      "text": "vorräthig, ich habe aber in Leipzig bey Breitkopf ein Exemplar gesehen, das er für vier Thaler"
    },
    {
      "text": "abläßt."
    },
    {
      "text": "Mit vollkommener Hochachtung verharre ich"
    },
    {
      "text": "Ew. Wohlgeborne ergebenster Diener"
    },
    {
      "text": "J. G. Lehmann."
    }
  ],
  "script": "kurrent",
  "notes": "Very neat and legible handwriting."
}

